def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for c in range(1, w - 1):
        # A crossbar has a one-cell gap in this column, flanked by its own color.
        bars = []
        for r in range(h):
            color = grid[r][c - 1]
            if (grid[r][c] == 0 and color != 0 and grid[r][c + 1] == color):
                bars.append((r, color))
        if not bars:
            continue
        # Each crossbar sets the vertical color down to the next crossbar.
        start = 0
        for r, color in bars:
            for rr in range(start, r + 1):
                out[rr][c] = color
            start = r + 1
        # A separate vertical marker below the final crossbar supplies the
        # color for the remaining segment, which reaches back to that bar.
        last = bars[-1][0]
        marker = next((grid[r][c] for r in range(last + 1, h) if grid[r][c] != 0), 0)
        if marker:
            for rr in range(last + 1, h):
                out[rr][c] = marker
    return out
